import unittest

from cart import cart_total


class CartTotalTest(unittest.TestCase):
    def test_single_item(self):
        """A single (price, qty) pair contributes price * qty."""
        self.assertEqual(cart_total([(10.0, 2)]), 20.0)

    def test_multiple_items(self):
        """Totals sum across items: 2.5*4 + 10*1 = 20.0."""
        self.assertAlmostEqual(cart_total([(2.5, 4), (10.0, 1)]), 20.0)

    def test_empty_cart(self):
        self.assertEqual(cart_total([]), 0)

    def test_zero_quantity(self):
        """A zero-quantity item contributes nothing."""
        self.assertEqual(cart_total([(5.0, 0)]), 0)


if __name__ == "__main__":
    unittest.main()
